package pl.mojealterego.omega.bridge;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Intent;
import android.content.SharedPreferences;
import android.net.Uri;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;

import androidx.annotation.Nullable;
import androidx.core.app.NotificationCompat;

import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;

import org.json.JSONObject;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

public class KnowledgeBridgeService extends Service {
    private static final String PREFS = "omega_bridge";
    private static final String CHANNEL = "omega_bridge";
    private static final int NOTIFICATION_ID = 8801;

    private final Handler handler = new Handler(Looper.getMainLooper());
    private final ExecutorService worker = Executors.newSingleThreadExecutor();
    private OkHttpClient client;
    private WebSocket socket;
    private volatile boolean authenticated = false;

    @Override
    public void onCreate() {
        super.onCreate();
        PDFBoxResourceLoader.init(getApplicationContext());
        createChannel();
        setConnectionStatus("ŁĄCZY...");
        startForeground(NOTIFICATION_ID, notification("Łączenie z OMEGA..."));
        client = new OkHttpClient.Builder()
                .pingInterval(20, TimeUnit.SECONDS)
                .retryOnConnectionFailure(true)
                .build();
        connect();
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (socket == null) connect();
        return START_STICKY;
    }

    private void connect() {
        SharedPreferences prefs = getSharedPreferences(PREFS, MODE_PRIVATE);
        String token = prefs.getString("agent_token", "");
        String wsUrl = prefs.getString("websocket_url", "");
        String treeUri = prefs.getString("tree_uri", "");
        if (token.isEmpty() || wsUrl.isEmpty() || treeUri.isEmpty()) {
            setConnectionStatus("BRAK KONFIGURACJI");
            updateNotification("Brak konfiguracji parowania lub folderu.");
            stopSelf();
            return;
        }

        setConnectionStatus("ŁĄCZY...");
        Request request = new Request.Builder().url(wsUrl).build();
        socket = client.newWebSocket(request, new WebSocketListener() {
            @Override
            public void onOpen(WebSocket webSocket, Response response) {
                authenticated = false;
                setConnectionStatus("UWIERZYTELNIA...");
                try {
                    webSocket.send(new JSONObject()
                            .put("type", "auth")
                            .put("token", token)
                            .toString());
                } catch (Exception ignored) {
                }
            }

            @Override
            public void onMessage(WebSocket webSocket, String text) {
                try {
                    JSONObject msg = new JSONObject(text);
                    String type = msg.optString("type");
                    if ("auth_ok".equals(type)) {
                        authenticated = true;
                        setConnectionStatus("POŁĄCZONO");
                        updateNotification("Połączono. BAZA WIEDZY jest dostępna read-only.");
                        return;
                    }
                    if ("request".equals(type)) {
                        worker.submit(() -> handleRequest(webSocket, msg, Uri.parse(treeUri)));
                    }
                } catch (Exception ignored) {
                }
            }

            @Override
            public void onClosed(WebSocket webSocket, int code, String reason) {
                authenticated = false;
                socket = null;
                setConnectionStatus("ROZŁĄCZONO (" + code + ")");
                scheduleReconnect();
            }

            @Override
            public void onFailure(WebSocket webSocket, Throwable t, Response response) {
                authenticated = false;
                socket = null;
                String message = t == null || t.getMessage() == null ? "nieznany błąd" : t.getMessage();
                setConnectionStatus("BŁĄD: " + message);
                updateNotification("Rozłączono. Ponawiam połączenie...");
                scheduleReconnect();
            }
        });
    }

    private void handleRequest(WebSocket webSocket, JSONObject msg, Uri treeUri) {
        String id = msg.optString("id", "");
        JSONObject params = msg.optJSONObject("params");
        if (params == null) params = new JSONObject();
        JSONObject response = new JSONObject();
        try {
            KnowledgeRoot root = new KnowledgeRoot(getApplicationContext(), treeUri);
            Object result;
            switch (msg.optString("method")) {
                case "knowledge.info":
                    result = root.info();
                    break;
                case "knowledge.list":
                    result = root.list(params);
                    break;
                case "knowledge.metadata":
                    result = root.metadata(params.optString("path"));
                    break;
                case "knowledge.read":
                    result = root.read(params);
                    break;
                case "knowledge.search":
                    result = root.search(params);
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported method");
            }
            response.put("type", "response").put("id", id).put("ok", true).put("result", result);
        } catch (Exception e) {
            try {
                response.put("type", "response")
                        .put("id", id)
                        .put("ok", false)
                        .put("error", new JSONObject().put("message", e.getMessage()));
            } catch (Exception ignored) {
            }
        }
        webSocket.send(response.toString());
    }

    private void scheduleReconnect() {
        handler.removeCallbacksAndMessages(null);
        handler.postDelayed(this::connect, 5000);
    }

    private void createChannel() {
        NotificationManager nm = getSystemService(NotificationManager.class);
        nm.createNotificationChannel(new NotificationChannel(
                CHANNEL, "OMEGA Knowledge Bridge", NotificationManager.IMPORTANCE_LOW));
    }

    private Notification notification(String text) {
        return new NotificationCompat.Builder(this, CHANNEL)
                .setSmallIcon(android.R.drawable.stat_sys_upload_done)
                .setContentTitle("OMEGA Knowledge Bridge")
                .setContentText(text)
                .setOngoing(true)
                .build();
    }

    private void updateNotification(String text) {
        NotificationManager nm = getSystemService(NotificationManager.class);
        nm.notify(NOTIFICATION_ID, notification(text));
    }

    private void setConnectionStatus(String value) {
        getSharedPreferences(PREFS, MODE_PRIVATE)
                .edit()
                .putString("connection_status", value)
                .apply();
    }

    @Override
    public void onDestroy() {
        handler.removeCallbacksAndMessages(null);
        if (socket != null) socket.close(1000, "service stopped");
        worker.shutdownNow();
        if (client != null) client.dispatcher().executorService().shutdown();
        super.onDestroy();
    }

    @Nullable
    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }
}

package pl.mojealterego.omega.bridge;

import android.content.Intent;
import android.content.SharedPreferences;
import android.net.Uri;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.text.InputType;
import android.view.Gravity;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.Nullable;
import androidx.appcompat.app.AppCompatActivity;

import org.json.JSONObject;

import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public class MainActivity extends AppCompatActivity {
    private static final int PICK_TREE = 7001;
    private static final String PREFS = "omega_bridge";
    private static final String RELAY_BASE = "https://omega-termux-knowledge-relay.onrender.com";

    private SharedPreferences prefs;
    private TextView status;
    private EditText pairCode;
    private final ExecutorService io = Executors.newSingleThreadExecutor();
    private final Handler uiHandler = new Handler(Looper.getMainLooper());
    private final Runnable statusPoller = new Runnable() {
        @Override
        public void run() {
            refreshStatus();
            uiHandler.postDelayed(this, 1000);
        }
    };

    @Override
    protected void onCreate(@Nullable Bundle state) {
        super.onCreate(state);
        prefs = getSharedPreferences(PREFS, MODE_PRIVATE);
        setContentView(buildUi());
        refreshStatus();
        maybeStartService();
    }

    private LinearLayout buildUi() {
        int pad = (int) (20 * getResources().getDisplayMetrics().density);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(pad, pad, pad, pad);
        root.setGravity(Gravity.CENTER_HORIZONTAL);

        TextView title = new TextView(this);
        title.setText("OMEGA Knowledge Bridge");
        title.setTextSize(26);
        root.addView(title, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        TextView subtitle = new TextView(this);
        subtitle.setText("Read-only dostęp do BAZA WIEDZY dla OMEGA MCP. Bez Termuxa.");
        subtitle.setTextSize(16);
        LinearLayout.LayoutParams subLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        subLp.setMargins(0, pad / 2, 0, pad);
        root.addView(subtitle, subLp);

        pairCode = new EditText(this);
        pairCode.setHint("Kod parowania");
        pairCode.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_VARIATION_PASSWORD);
        root.addView(pairCode, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        Button pair = new Button(this);
        pair.setText("1. Sparuj z OMEGA");
        pair.setOnClickListener(v -> pairRelay());
        root.addView(pair, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        Button folder = new Button(this);
        folder.setText("2. Wybierz folder BAZA WIEDZY");
        folder.setOnClickListener(v -> chooseFolder());
        root.addView(folder, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        Button start = new Button(this);
        start.setText("3. Uruchom most");
        start.setOnClickListener(v -> {
            maybeStartService();
            refreshStatus();
        });
        root.addView(start, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        status = new TextView(this);
        status.setTextSize(15);
        LinearLayout.LayoutParams stLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        stLp.setMargins(0, pad, 0, 0);
        root.addView(status, stLp);
        return root;
    }

    private void pairRelay() {
        String code = pairCode.getText().toString().trim();
        if (code.isEmpty()) {
            Toast.makeText(this, "Wpisz kod parowania.", Toast.LENGTH_SHORT).show();
            return;
        }
        status.setText("Parowanie...");
        io.submit(() -> {
            OkHttpClient client = new OkHttpClient();
            try {
                JSONObject body = new JSONObject().put("code", code);
                Request req = new Request.Builder()
                        .url(RELAY_BASE + "/pair")
                        .post(RequestBody.create(body.toString(), MediaType.get("application/json; charset=utf-8")))
                        .build();
                try (Response response = client.newCall(req).execute()) {
                    String text = response.body() == null ? "" : response.body().string();
                    if (!response.isSuccessful()) {
                        throw new IOException("Parowanie odrzucone: HTTP " + response.code());
                    }
                    JSONObject result = new JSONObject(text);
                    String token = result.getString("agent_token");
                    String wsUrl = result.getString("websocket_url");
                    prefs.edit()
                            .putString("agent_token", token)
                            .putString("websocket_url", wsUrl)
                            .apply();
                    runOnUiThread(() -> {
                        pairCode.setText("");
                        Toast.makeText(this, "Sparowano.", Toast.LENGTH_SHORT).show();
                        refreshStatus();
                        maybeStartService();
                    });
                }
            } catch (Exception e) {
                runOnUiThread(() -> status.setText("Błąd parowania: " + e.getMessage()));
            }
        });
    }

    private void chooseFolder() {
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION
                | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION
                | Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);
        startActivityForResult(intent, PICK_TREE);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode != PICK_TREE || resultCode != RESULT_OK || data == null || data.getData() == null) return;
        Uri uri = data.getData();
        try {
            getContentResolver().takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
        } catch (SecurityException ignored) {
        }
        prefs.edit().putString("tree_uri", uri.toString()).apply();
        refreshStatus();
        maybeStartService();
    }

    private void maybeStartService() {
        String token = prefs.getString("agent_token", "");
        String tree = prefs.getString("tree_uri", "");
        if (token.isEmpty() || tree.isEmpty()) return;
        prefs.edit().putString("connection_status", "ŁĄCZY...").apply();
        Intent service = new Intent(this, KnowledgeBridgeService.class);
        startForegroundService(service);
    }

    private void refreshStatus() {
        if (status == null) return;
        boolean paired = !prefs.getString("agent_token", "").isEmpty();
        boolean folder = !prefs.getString("tree_uri", "").isEmpty();
        String bridge = prefs.getString("connection_status",
                paired && folder ? "OCZEKUJE" : "NIEAKTYWNY");
        status.setText("Parowanie: " + (paired ? "OK" : "BRAK")
                + "\nFolder: " + (folder ? "OK" : "BRAK")
                + "\nMost: " + bridge);
    }

    @Override
    protected void onResume() {
        super.onResume();
        uiHandler.removeCallbacks(statusPoller);
        uiHandler.post(statusPoller);
    }

    @Override
    protected void onPause() {
        uiHandler.removeCallbacks(statusPoller);
        super.onPause();
    }

    @Override
    protected void onDestroy() {
        uiHandler.removeCallbacks(statusPoller);
        io.shutdownNow();
        super.onDestroy();
    }
}
